-- 0013_master_railways.sql
-- 全国の路線(602 件)と駅(8988 件)のマスタを投入する。
--
-- **このファイルは scripts/build_master_data.mjs が生成した。手で編集しないこと。**
-- 再生成: node scripts/build_master_data.mjs
--
-- 出典:
--   - Seo-4d696b75/station_database out/main (CC BY 4.0)
--   -   https://github.com/Seo-4d696b75/station_database
--   -   クレジット表示はアプリ内「データ出典」画面で行う
--
-- 非開示要件への影響(AGENTS.md R-1〜R-5): なし。
-- 全ログインユーザーが参照してよい公開マスタで、個人情報もインサイトも含まない。
-- RLS ポリシー(0004 の *_select_all)と GRANT(0009)は既存のものがそのまま効く。

-- 駅名検索(部分一致)を実用的な速度にする。
create extension if not exists pg_trgm;

alter table public.railway_lines
  add column if not exists name_kana      text,
  add column if not exists company_code   int,
  add column if not exists prefecture_ids int[] not null default '{}';

comment on column public.railway_lines.prefecture_ids is
  '所属駅の都道府県。都道府県から路線を絞り込むための非正規化列。';

alter table public.stations
  add column if not exists name_kana     text,
  add column if not exists prefecture_id int references public.prefectures(id);

-- 動作確認用の暫定データを入れ替える。参照を外してから作り直す。
update public.client_profiles set nearest_station_id = null where nearest_station_id is not null;
update public.campaigns       set nearest_station_id = null where nearest_station_id is not null;
delete from public.stations;
delete from public.railway_lines;

