on conflict (id) do update
  set line_id       = excluded.line_id,
      name          = excluded.name,
      name_kana     = excluded.name_kana,
      latitude      = excluded.latitude,
      longitude     = excluded.longitude,
      prefecture_id = excluded.prefecture_id;

select setval('public.stations_id_seq', (select max(id) from public.stations));

create index if not exists railway_lines_prefecture_idx
  on public.railway_lines using gin (prefecture_ids);
create index if not exists stations_prefecture_idx
  on public.stations (prefecture_id);
create index if not exists stations_name_trgm_idx
  on public.stations using gin (name gin_trgm_ops);
